// A schematic navigator: geometry stays legible without shrinking world artwork.
const miniCanvas=$('miniMap');miniCanvas.width=300;miniCanvas.height=190;
miniCanvas.setAttribute('aria-label','Mini harita: beyaz ok sen, altın noktalar NPC, mor elmaslar portal. M ile büyük harita.');
const mapFrame=$('worldReadout');
mapFrame.insertAdjacentHTML('afterbegin','<div class="mini-heading"><b>KEŞİF HARİTASI</b><span>M · Büyüt</span></div>');
mapFrame.insertAdjacentHTML('beforeend','<div class="mini-key"><span class="you">▲ Sen</span><span class="npc">● NPC</span><span class="portal">◆ Geçit</span></div>');
function miniMarker(g,x,y,color,kind='dot',size=4){g.save();g.translate(x,y);g.fillStyle=color;g.strokeStyle='#08121d';g.lineWidth=2;g.beginPath();if(kind==='diamond'){g.moveTo(0,-size-1);g.lineTo(size+1,0);g.lineTo(0,size+1);g.lineTo(-size-1,0);g.closePath()}else g.arc(0,0,size,0,Math.PI*2);g.fill();g.stroke();g.restore()}
function miniPlayer(g,x,y){g.save();g.translate(x,y);const angle={up:0,right:Math.PI/2,down:Math.PI,left:-Math.PI/2}[p.facing]||0;g.rotate(angle);g.shadowColor='#8eeeff';g.shadowBlur=7;g.fillStyle='#ffffff';g.strokeStyle='#071724';g.lineWidth=2;g.beginPath();g.moveTo(0,-7);g.lineTo(5,5);g.lineTo(0,3);g.lineTo(-5,5);g.closePath();g.fill();g.stroke();g.restore()}
function miniGrid(g,w,h){g.fillStyle='#101e29';g.fillRect(0,0,w,h);g.strokeStyle='#233542';g.lineWidth=1;for(let x=10;x<w;x+=24){g.beginPath();g.moveTo(x,0);g.lineTo(x,h);g.stroke()}for(let y=10;y<h;y+=24){g.beginPath();g.moveTo(0,y);g.lineTo(w,y);g.stroke()}}
function drawVillageNavigator(g=miniCanvas.getContext('2d'),w=300,h=190){const s=Math.min((w-24)/HUB.w,(h-20)/HUB.h),ox=(w-HUB.w*s)/2,oy=(h-HUB.h*s)/2,X=x=>ox+x*s,Y=y=>oy+y*s;miniGrid(g,w,h);g.fillStyle='#233b39';g.fillRect(ox,oy,HUB.w*s,HUB.h*s);g.fillStyle='#687263';g.fillRect(X(PLAZA.x),Y(PLAZA.y),PLAZA.w*s,PLAZA.h*s);g.lineJoin='round';g.lineCap='round';for(const r of townRoads){g.beginPath();r.points.forEach(([x,y],i)=>i?g.lineTo(X(x),Y(y)):g.moveTo(X(x),Y(y)));g.strokeStyle='#a4ac91';g.lineWidth=Math.max(2,r.width*s);g.stroke()}for(const b of [...buildings,...townLandmarks]){g.fillStyle='#101d26';g.fillRect(X(b.x)-1,Y(b.y)-1,b.w*s+2,b.h*s+2);g.fillStyle='#687e8b';g.fillRect(X(b.x),Y(b.y),b.w*s,b.h*s)}for(const n of services)miniMarker(g,X(n.x),Y(n.y),npcInfo[n.id]?'#f3c979':'#be9bff',npcInfo[n.id]?'dot':'diamond',3);const d=activeDestination();if(d){g.setLineDash([4,3]);g.strokeStyle='#ffe293';g.lineWidth=1.5;g.beginPath();g.moveTo(X(p.x),Y(p.y));g.lineTo(X(d.x),Y(d.y));g.stroke();g.setLineDash([]);g.strokeRect(X(d.x)-7,Y(d.y)-7,14,14)}g.strokeStyle='#b8e9ff77';g.lineWidth=1;g.strokeRect(X(camera.x),Y(camera.y),VIEW.w*s,VIEW.h*s);miniPlayer(g,X(p.x),Y(p.y));}
const readoutBeforeNavigator=updateWorldReadout;updateWorldReadout=function(dt){readoutBeforeNavigator(dt);if(p.area==='hub')drawVillageNavigator()};
const dungeonMapBeforeNavigator=drawDungeonMap;drawDungeonMap=function(g,w,h){if(g===miniCanvas.getContext('2d')){w=300;h=190;}miniGrid(g,w,h);const s=Math.min((w-24)/DUNGEON.w,(h-24)/DUNGEON.h),ox=(w-DUNGEON.w*s)/2,oy=(h-DUNGEON.h*s)/2,X=x=>ox+x*s,Y=y=>oy+y*s;for(const r of DUNGEON.corridors){g.fillStyle='#8a9da5';g.fillRect(X(r.x),Y(r.y),Math.max(3,r.w*s),Math.max(3,r.h*s))}DUNGEON.rooms.forEach((r,n)=>{const open=dungeonRoomOpen(n),clear=n>0&&n<DUNGEON.bossRoom&&!roomRemaining(n);g.fillStyle=n===0?'#466f78':!open?'#24323f':clear?'#356d5d':n===DUNGEON.bossRoom?'#713e54':'#70634b';g.fillRect(X(r.x),Y(r.y),r.w*s,r.h*s);g.strokeStyle=n===dungeonRoom?'#ffffff':clear?'#80d4ad':open?'#bbac88':'#556575';g.lineWidth=n===dungeonRoom?2:1;g.strokeRect(X(r.x),Y(r.y),r.w*s,r.h*s);g.fillStyle=open?'#f0e7cf':'#94a4b5';g.font='bold 10px Segoe UI';g.textAlign='center';g.fillText(n===0?'G':n===DUNGEON.bossRoom?'B':String(n),X(r.x+r.w/2),Y(r.y)+11)});for(const gate of DUNGEON.gates){g.fillStyle=dungeonGateLocked(gate)?'#ffad66':'#83d6aa';g.fillRect(X(gate.x)-1,Y(gate.y)-1,Math.max(3,gate.w*s),Math.max(3,gate.h*s))}for(const e of enemies)if(!e.dead&&dungeonRoomOpen(e.dungeonRoom))miniMarker(g,X(e.x),Y(e.y),e.boss?'#ffcf77':'#ff777b',e.boss?'diamond':'dot',e.boss?5:2);miniMarker(g,X(DUNGEON.entry.x),Y(DUNGEON.entry.y),'#be9bff','diamond',4);if(dungeonRun.complete)miniMarker(g,X(DUNGEON.exit.x),Y(DUNGEON.exit.y),'#be9bff','diamond',4);miniPlayer(g,X(p.x),Y(p.y));};
const dungeonReadoutBeforeNavigator=updateDungeonReadout;updateDungeonReadout=function(){dungeonReadoutBeforeNavigator();document.querySelector('.mini-key').innerHTML='<span class="you">▲ Sen</span><span class="enemy">● Düşman</span><span class="clear">■ Temiz oda</span>'};
const returnBeforeNavigator=returnVillage;returnVillage=function(){returnBeforeNavigator();document.querySelector('.mini-key').innerHTML='<span class="you">▲ Sen</span><span class="npc">● NPC</span><span class="portal">◆ Geçit</span>'};
// Both map sizes now use the same geometry, palette and markers.
drawMap=function(){const c=$('mapCanvas'),g=c.getContext('2d'),w=c.width,h=c.height,hub=p.area==='hub';if(hub)drawVillageNavigator(g,w,h);else drawDungeonMap(g,w,h);$('mapTitle').textContent=hub?'Ocak Köyü · Keşif haritası':'Kara Taş Mahzeni · Oda planı';$('mapLegend').textContent=hub?'▲ Sen · Altın: köylüler · Mor: geçitler · Açık çizgiler: yollar. Aşağıdan hedef seçebilirsin.':'▲ Sen · Kırmızı: düşman · Yeşil: temiz oda · Turuncu: mühür · G: giriş · B: boss. Odaları sırayla temizle.';const world=hub?HUB:DUNGEON,s=Math.min((w-24)/world.w,(h-(hub?20:24))/world.h),ox=(w-world.w*s)/2,oy=(h-world.h*s)/2;g.font='11px Segoe UI';g.textAlign='center';if(hub){for(const n of services){const x=ox+n.x*s,y=oy+n.y*s+16,t=n.name.split(' · ').pop();g.lineWidth=4;g.strokeStyle='#0b1624';g.strokeText(t,x,y);g.fillStyle=npcInfo[n.id]?'#ffe0a0':'#d3bdff';g.fillText(t,x,y)}}else DUNGEON.rooms.forEach((r,n)=>{g.font='9px Segoe UI';g.fillStyle='#e1dccb';g.fillText(r.name,ox+(r.x+r.w/2)*s,oy+(r.y+r.h/2)*s+6,Math.max(40,r.w*s-6))})};


